class CtlHorizontal{constructor(){this.CtlHrLoop()}CtlHrLoop(){this.parentWrp=jQuery(".ctl-horizontal-wrapper"),this.parentWrp.map((key,ele)=>{const mainSwiper=jQuery(ele).find(".ctl-slider-container")[0];this.initializeMainSlider(mainSwiper)})}initializeMainSlider=element=>{if(!element)return;const swiperAttr=this.ctlSlideAttribute(element);new Swiper(element,swiperAttr)};ctlSlideAttribute=wrapper=>{const parentWrp=wrapper.closest(".ctl-horizontal-wrapper"),element=jQuery(parentWrp),nextButton=element.find(".ctl-button-next")[0],prevButton=element.find(".ctl-button-prev")[0],showSlides=""===element.data("items")?6:parseInt(element.data("items")),attribute={slidesPerGroup:1,slidesPerView:1,breakpoints:{640:{slidesPerView:1},768:{slidesPerView:2},1024:{slidesPerView:showSlides}}};return nextButton&&prevButton&&(attribute.navigation={nextEl:nextButton,prevEl:prevButton,addIcons:!1}),attribute}}new CtlHorizontal;